<script setup lang="ts">
import { computed, nextTick, onMounted, onUnmounted, ref } from 'vue'
import { useRouter } from 'vue-router'
import { BookOpen, Images, Search, FolderOpen, Plus, LayoutGrid, List, Heart, Settings2, Clock3, ArrowUpDown } from 'lucide-vue-next'
import { useImageStore } from '@/stores/image'
import { rememberScroll, recallScroll } from '@/composables/useModules'
import ImageCover from '@/components/image/ImageCover.vue'
import ImageShelf from '@/components/image/ImageShelf.vue'
import ImageCollectionDialog from '@/components/image/ImageCollectionDialog.vue'
import { useLibraryView } from '@/composables/useLibraryView'
import ImageImportDialog from '@/components/image/ImageImportDialog.vue'
import ImageGroupDialog from '@/components/image/ImageGroupDialog.vue'
import SourceDialog from '@/components/image/SourceDialog.vue'
import '@/components/image/image.css'
import type { ImageItem, ImageType } from '@/types/image'
const store=useImageStore(), router=useRouter(), importer=ref(false), manager=ref(false), source=ref(false)
const {grouping,cardSize,layout}=useLibraryView('image')
const collection=ref('')
const search=ref<HTMLInputElement>(), scroll=ref<HTMLElement>()
const title=computed(()=>store.query.type==='photo'?'我的相册':'漫画书架')
const tags=computed(()=>[...new Set(store.items.filter(i=>i.type===store.query.type).flatMap(i=>i.tags))].sort())
const directories=computed(()=>[...new Set(store.items.filter(i=>i.type===store.query.type).map(i=>i.sourceDir).filter(Boolean))])
const continuing=computed(()=>store.shown.filter(i=>i.progress).sort((a,b)=>b.progress!.updatedAt-a.progress!.updatedAt).slice(0,4))
function changeType(type:ImageType){store.query={type,sort:store.query.sort}; if(scroll.value)scroll.value.scrollTop=0}
function open(item:ImageItem,read=false){void router.push({name:'image-detail',params:{id:item.id},query:read?{read:'1'}:{}})}
function progress(item:ImageItem){return item.progress && item.pageCount ? Math.round((item.progress.ordinal+1)/item.pageCount*100):0}
function keys(event:KeyboardEvent){if((event.ctrlKey||event.metaKey)&&event.key.toLowerCase()==='k'){event.preventDefault();search.value?.focus()}}
onMounted(async()=>{window.addEventListener('keydown',keys);await store.refresh();await nextTick();if(scroll.value)scroll.value.scrollTop=recallScroll('image')})
onUnmounted(()=>{window.removeEventListener('keydown',keys);if(scroll.value)rememberScroll('image',scroll.value.scrollTop)})
</script>
<template><div class="im-page image-home"><aside class="image-sidebar"><nav aria-label="图片分类"><button :class="{on:store.query.type==='photo'}" @click="changeType('photo')"><Images :size="20"/>照片</button><button :class="{on:store.query.type==='comic'}" @click="changeType('comic')"><BookOpen :size="20"/>漫画</button></nav>
  <div v-if="store.query.type==='comic'" class="image-types"><button :class="{selected:!store.query.groupId&&!store.query.uncategorized}" @click="store.query.groupId=undefined;store.query.uncategorized=false"><span>●</span>全部漫画</button><button :class="{selected:store.query.uncategorized}" @click="store.query.groupId=undefined;store.query.uncategorized=true"><span>●</span>未分类</button><button v-for="group in store.groups.filter(g=>!g.hidden)" :key="group.id" :class="{selected:store.query.groupId===group.id}" @click="store.query.groupId=group.id;store.query.uncategorized=false"><span>●</span>{{group.name}}</button><button @click="manager=true"><Plus :size="17"/>新增／管理分类</button></div>
  <div class="image-filters"><button :class="{selected:store.query.favorite}" @click="store.query.favorite=!store.query.favorite"><Heart :size="15"/>收藏</button></div>
  <label class="im-field">阅读状态<select v-model="store.query.read" aria-label="筛选已读状态"><option :value="undefined">全部阅读状态</option><option :value="true">已读</option><option :value="false">未读</option></select></label>
  <div v-if="tags.length" class="image-tags"><h3>标签</h3><button v-for="tag in tags" :key="tag" :class="{selected:store.query.tag===tag}" @click="store.query.tag=store.query.tag===tag?undefined:tag">{{tag}}</button></div>
  <label v-if="store.query.type==='photo' && directories.length" class="im-field">来源目录<select v-model="store.query.sourceDir" aria-label="相册来源目录"><option :value="undefined">全部目录</option><option v-for="dir in directories" :key="dir" :value="dir">{{dir.split(/[\\/]/).at(-1)}}</option></select></label>
  <button class="image-settings" @click="router.push('/settings')"><Settings2 :size="17"/>设置</button>
</aside><main ref="scroll" class="image-content"><header class="image-toolbar"><h1>{{title}}</h1><label class="image-search"><Search :size="19"/><input ref="search" v-model="store.query.search" placeholder="搜索名称、说明或标签…" aria-label="搜索图片库"/><kbd>Ctrl K</kbd></label><label class="image-sort"><ArrowUpDown :size="16"/><select v-model="store.query.sort" aria-label="图片排序"><option value="updated">最近更新</option><option value="name">名称排序</option><option value="read">最近阅读</option></select></label><select v-model="grouping" aria-label="漫画分组"><option value="none">不分组</option><option value="category">按分类分组</option><option value="directory">按文件夹分组</option></select><label class="image-card-size">卡片大小<input v-model.number="cardSize" type="range" min="110" max="260" step="10" aria-label="漫画卡片大小"/></label><div class="image-view"><button :class="{selected:layout==='grid'}" aria-label="网格视图" @click="layout='grid'"><LayoutGrid :size="18"/></button><button :class="{selected:layout==='list'}" aria-label="列表视图" @click="layout='list'"><List :size="18"/></button></div><button class="im-button" @click="importer=true"><FolderOpen :size="18"/>导入目录</button><button v-if="store.query.type==='comic'" class="im-button im-primary" @click="source=true"><Plus :size="19"/>从哔咔添加</button></header>
  <p v-if="store.error" class="im-error" role="alert">{{store.error}} <button @click="store.refresh()">重试</button></p>
  <section v-if="continuing.length && store.query.type==='comic'" class="image-continue"><h2><Clock3 :size="18"/>继续阅读</h2><div><button v-for="item in continuing" :key="item.id" class="continue-card" @click="open(item,true)"><ImageCover :page-id="item.coverPageId" :name="item.name"/><div><strong>{{item.name}}</strong><p>{{item.chapters.find(c=>c.id===item.progress?.chapterId)?.title || '未分章'}}</p><p>第 {{(item.progress?.ordinal||0)+1}} / {{item.pageCount}} 页</p><div class="continue-progress"><div class="im-progress"><span :style="{width:progress(item)+'%'}"/></div><small>{{progress(item)}}%</small></div></div></button></div></section>
  <section><div class="image-section-title"><h2>{{store.query.type==='comic'?'我的漫画书架':'相册'}}</h2><span>{{store.shown.length}} {{store.query.type==='comic'?'部作品':'个相册'}}</span></div><div v-if="!store.items.length && store.loading" class="im-empty">正在载入图片库…</div><div v-else-if="!store.shown.length" class="im-empty"><BookOpen v-if="store.query.type==='comic'" :size="48"/><Images v-else :size="48"/><h2>{{store.items.some(i=>i.type===store.query.type)?'没有符合条件的内容':'从一个本地文件夹开始'}}</h2><p>照片按相册归档，漫画按作品阅读。<br/>导入后，断网也能随时打开。</p><button class="im-button im-primary" @click="importer=true"><FolderOpen :size="18"/>导入{{store.query.type==='comic'?'漫画':'相册'}}</button></div>
  <ImageShelf v-else v-model:page="store.shelfPage" :items="store.shown" :groups="store.groups" :type="store.query.type||'comic'" :layout="layout" :query-key="JSON.stringify(store.query)" :grouping="grouping" :card-size="cardSize" :roots="directories" @collection="collection=$event" @open="open"/></section>
</main><ImageImportDialog v-if="importer" :type="store.query.type||'comic'" @close="importer=false"/><ImageGroupDialog v-if="manager" @close="manager=false"/><ImageCollectionDialog v-if="collection" :id="collection" @close="collection=''" @open="collection='';open($event)"/><SourceDialog v-if="source" @close="source=false"/></div></template>
<style scoped>
.image-home{display:flex;overflow:hidden}.image-sidebar{width:var(--sidebar-w);flex:none;background:var(--bg-side);border-right:1px solid var(--divider);padding:24px 12px 16px;display:flex;flex-direction:column;overflow:auto}.image-sidebar nav{display:grid;gap:6px}.image-sidebar nav button{display:flex;align-items:center;gap:14px;text-align:left;padding:13px 16px;border-radius:7px;font-size:15px;color:var(--text-sub);position:relative}.image-sidebar nav .on{background:var(--active-surface);color:var(--accent)}.image-sidebar nav .on:before{content:'';position:absolute;left:0;top:9px;bottom:9px;width:3px;background:var(--accent);border-radius:5px}.image-types{padding:12px 10px 18px;display:grid;gap:2px}.image-types button{display:flex;align-items:center;gap:14px;color:var(--text-sub);text-align:left;min-height:34px;font-size:13px}.image-types span{font-size:8px;padding:0 4px}.image-sidebar .selected{color:var(--accent)}.image-filters{border-top:1px solid var(--divider);padding:20px 8px;display:flex;align-items:flex-start;flex-direction:column;gap:10px}.image-filters button{display:flex;gap:7px;background:var(--hover-surface);border-radius:18px;padding:5px 13px;color:var(--text-sub)}.image-tags{padding:0 8px 20px}.image-tags h3{color:var(--text-faint);font-size:12px;font-weight:400;margin:5px 0 12px}.image-tags button{color:var(--text-sub);font-size:12px;margin:0 7px 9px 0}.image-settings{display:flex;align-items:center;gap:10px;margin-top:auto;padding:14px;color:var(--text-sub)}.image-content{flex:1;min-width:0;overflow:auto;padding:25px 26px 45px}.image-toolbar{display:flex;align-items:center;gap:12px;flex-wrap:wrap;margin-bottom:27px}.image-toolbar h1{font-size:28px;letter-spacing:1px;margin:0 auto 0 0;font-weight:600;white-space:nowrap}.image-search{display:flex;gap:8px;align-items:center;background:var(--bg-card);border:1px solid var(--divider);border-radius:7px;padding:0 12px;flex:1;min-width:190px;max-width:450px;color:var(--text-sub)}.image-search input{border:0;background:transparent;padding:10px 0;width:100%;outline:none}.image-search kbd{white-space:nowrap;font-size:11px;color:var(--text-faint)}.image-sort{display:flex;align-items:center;gap:5px;color:var(--text-sub)}.image-sort select{border:0;background:transparent;padding:8px 0;max-width:100px}.image-view{display:flex;border:1px solid var(--divider);border-radius:7px;overflow:hidden}.image-view button{display:flex;padding:9px;color:var(--text-sub)}.image-view .selected{background:var(--active-surface);color:var(--accent)}h2{font-size:18px;font-weight:600;margin:0 0 16px}.image-continue{margin-bottom:30px}.image-continue h2{display:flex;align-items:center;gap:8px}.image-continue>div{display:grid;grid-template-columns:repeat(auto-fit,minmax(225px,1fr));gap:16px}.continue-card{display:flex;gap:13px;text-align:left;background:var(--bg-card);border:1px solid var(--divider);border-radius:8px;padding:7px;min-width:0;color:var(--text-main)}.continue-card>.image-cover{width:82px;border-radius:4px}.continue-card>div:last-child{min-width:0;flex:1;padding:6px 3px}.continue-card strong{display:block;overflow:hidden;white-space:nowrap;text-overflow:ellipsis;font-size:13px}.continue-card p{color:var(--text-sub);font-size:11px;margin:7px 0}.continue-progress{display:flex;align-items:center;gap:9px;margin-top:12px}.continue-progress>.im-progress{flex:1}.continue-progress small{font-size:10px;color:var(--text-sub)}.image-section-title{display:flex;align-items:baseline;gap:12px}.image-section-title>span{font-size:12px;color:var(--text-faint)}@media(max-width:1100px){.image-content{padding:20px}.image-toolbar h1{font-size:24px}.image-search{order:2;max-width:none;flex-basis:50%}.image-toolbar{gap:9px}.image-sidebar{width:180px}}
</style>
<style scoped>
@media(max-width:1200px){.image-continue>div{grid-template-columns:none;grid-auto-flow:column;grid-auto-columns:260px;overflow-x:auto;padding-bottom:6px}}
</style>

<style scoped>.image-card-size{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--text-sub)}.image-card-size input{width:90px;accent-color:var(--accent)}</style>
